// What gen.ts writes into load.ts and provider-vocab.ts beyond what
// @yaks/workerd/gen writes for any Worker: every package's words, and the
// words of the providers that answer the Operator. Pure: gen.ts reads the
// manifests and owns the generated files.
import { type Config, used } from '@yaks/host/config'
import type { Manifest } from '@yaks/workerd/gen'

/** Every package's `./vocab`, configured or not: an app names any of them as a
 * `"platform"` dependency, and its store speaks their words (vocab.ts
 * `lent`). A Worker cannot import a facet it was not bundled with. */
export let vocabs = (manifests: Manifest[]): string[] =>
  manifests.filter((m) =>
    m.name?.startsWith('@yaks/') && typeof m.exports == 'object' &&
    Object.hasOwn(m.exports, './vocab')
  ).map((m) => `${m.name}/vocab`)

/** The `./vocab` of each plugin a provider config names that declares one
 * (config.ts `providing`): the words its replies are recorded in. */
export let worded = (config: Config, manifests: Manifest[]): string[] =>
  [...new Set((config.plugins ?? []).map(used))].sort().filter((plugin) => {
    let exported = manifests.find((m) => m.name == plugin)?.exports
    return typeof exported == 'object' && Object.hasOwn(exported, './vocab')
  }).map((plugin) => `${plugin}/vocab`)

/** A module of the documents `specifiers` (each a plugin's `./vocab`)
 * declare, and no other package's: provider-vocab.ts, which the Operator's
 * store reads without load.ts's every vocabulary. */
export let worder = (specifiers: string[]): string =>
  [
    '// Generated by gen.ts from config.ts `providing`. Do not edit.',
    "import type { VocabDoc } from '@yaks/vocab'",
    ...specifiers.map((s, i) =>
      `import * as vocab${i} from ${JSON.stringify(s)}`
    ),
    '/** The words the configured providers record a reply with (their',
    ' * `./vocab`), for a store that keeps their replies. */',
    'export let providerDocs: VocabDoc[] = [',
    ...specifiers.map((_, i) => `vocab${i},`),
    '].flatMap((v) => v.docs ?? [])',
    '',
  ].join('\n')
